-- Fact accuracy fixes, November 10 2026. Each replace runs only if the old text is present. Safe to run more than once.
do $fix$
begin
  update public.course_items i set content = jsonb_set(i.content,'{body}',to_jsonb(replace(i.content->>'body',$o$cost about 620,000 soldiers' lives, the most of any American war$o$,$n$cost at least 620,000 soldiers' lives, the most of any American war$n$))) from public.courses c where c.id=i.course_id and c.slug='united-states-history-1' and i.kind='topic' and i.position=2 and position($o$cost about 620,000 soldiers' lives, the most of any American war$o$ in i.content->>'body')>0;
  update public.course_items i set content = jsonb_set(i.content,'{body}',to_jsonb(replace(i.content->>'body',$o$declared enslaved people in rebel states free. It made ending slavery a goal of the war, and about 180,000 Black men served in the Union army and navy.$o$,$n$declared enslaved people in the states still in rebellion free, though it did not apply to the loyal border states or to some areas already held by the Union. It made ending slavery a goal of the war, and nearly 200,000 Black men served in the Union army and navy.$n$))) from public.courses c where c.id=i.course_id and c.slug='united-states-history-1' and i.kind='topic' and i.position=2 and position($o$declared enslaved people in rebel states free. It made ending slavery a goal of the war, and about 180,000 Black men served in the Union army and navy.$o$ in i.content->>'body')>0;
  update public.course_items i set content = jsonb_set(i.content,'{body}',to_jsonb(replace(i.content->>'body',$o$Five days later Lincoln was shot and died.$o$,$n$Five days later, on April 14, Lincoln was shot, and he died the next morning.$n$))) from public.courses c where c.id=i.course_id and c.slug='united-states-history-1' and i.kind='topic' and i.position=2 and position($o$Five days later Lincoln was shot and died.$o$ in i.content->>'body')>0;
  update public.course_items i set content = jsonb_set(i.content,'{body}',to_jsonb(replace(i.content->>'body',$o$Embryology: early embryos of vertebrates look alike.$o$,$n$Embryology: the early embryos of vertebrates share similar features, such as pharyngeal arches.$n$))) from public.courses c where c.id=i.course_id and c.slug='biology-1' and i.kind='topic' and i.position=17 and position($o$Embryology: early embryos of vertebrates look alike.$o$ in i.content->>'body')>0;
  update public.course_items i set content = jsonb_set(i.content,'{body}',to_jsonb(replace(i.content->>'body',$o$The oldest fossils of cells are about 3.5 billion years old.$o$,$n$The oldest widely accepted fossils of cells are at least about 3.5 billion years old.$n$))) from public.courses c where c.id=i.course_id and c.slug='biology-1' and i.kind='topic' and i.position=19 and position($o$The oldest fossils of cells are about 3.5 billion years old.$o$ in i.content->>'body')>0;
  update public.course_items i set content = jsonb_set(i.content,'{body}',to_jsonb(replace(i.content->>'body',$o$Islam honors Jesus as a prophet but denies his deity and his crucifixion.$o$,$n$Islam honors Jesus as a prophet but teaches that he is not divine, and most Muslims believe he was not crucified.$n$))) from public.courses c where c.id=i.course_id and c.slug='world-history-1' and i.kind='topic' and i.position=7 and position($o$Islam honors Jesus as a prophet but denies his deity and his crucifixion.$o$ in i.content->>'body')>0;
  update public.course_items i set content = jsonb_set(i.content,'{body}',to_jsonb(replace(i.content->>'body',$o$On October 31, 1517, Martin Luther, a monk and professor in Wittenberg, Germany, posted Ninety Five Theses$o$,$n$On October 31, 1517, according to long tradition, Martin Luther, a monk and professor in Wittenberg, Germany, posted Ninety Five Theses$n$))) from public.courses c where c.id=i.course_id and c.slug='world-history-1' and i.kind='topic' and i.position=18 and position($o$On October 31, 1517, Martin Luther, a monk and professor in Wittenberg, Germany, posted Ninety Five Theses$o$ in i.content->>'body')>0;
